WHERE (scope, seq) IN (
	SELECT doomed.scope, doomed.seq
	FROM audit_log_entries AS doomed
	WHERE doomed.scope = sqlc.arg(scope)
		AND doomed.seq <= sqlc.arg(through_seq)
	ORDER BY doomed.seq ASC
	LIMIT sqlc.arg(result_limit)
	FOR UPDATE SKIP LOCKED
);

